INSERT INTO `chatbot_small_talk` VALUES (1,'social','Xin chào','xin chào','Xin chào anh/chị. Anh/chị cần tôi hỗ trợ thông tin gì?','[\"xin chao\", \"chao ban\", \"chao anh\", \"chao chi\", \"hi\", \"hello\"]',1,1,0,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(2,'social','Chào buổi sáng','chào buổi sáng','Dạ, kính chào anh/chị. Chúc anh/chị một ngày tốt lành. Anh/chị cần tôi hỗ trợ thông tin gì về tái hòa nhập cộng đồng ạ?','[\"chao buoi sang\", \"chao buoi chieu\", \"chao buoi toi\", \"buoi sang tot lanh\"]',1,1,1,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(3,'social','Có ai ở đây không','có ai ở đây không','Dạ có tôi đây ạ. Tôi là Trợ lý ảo Hướng Thiện, luôn sẵn sàng hỗ trợ anh/chị. Anh/chị cứ nhắn câu hỏi cho tôi nhé.','[\"co ai khong\", \"co ai o day khong\", \"co ai do khong\", \"alo co ai khong\"]',1,1,2,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(4,'social','Cảm ơn','cảm ơn','Dạ không có gì ạ. Anh/chị cần hỏi thêm điều gì về tái hòa nhập cộng đồng, cứ nhắn cho tôi nhé.','[\"cam on\", \"cam on ban\", \"cam on nhieu\", \"cam on nhe\", \"da cam on\", \"thanks\"]',1,1,3,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(5,'social','Tạm biệt','tạm biệt','Cảm ơn anh/chị đã liên hệ. Chúc anh/chị nhiều sức khỏe và thuận lợi. Khi cần hỗ trợ, anh/chị có thể quay lại đây hoặc gọi đường dây nóng 0903.480.985.','[\"tam biet\", \"chao tam biet\", \"hen gap lai\", \"toi di day\", \"minh di nhe\", \"bye\", \"goodbye\"]',1,1,4,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(6,'social','Xin lỗi','xin lỗi','Dạ không sao đâu ạ. Anh/chị cứ thoải mái nhắn câu hỏi, tôi luôn sẵn sàng hỗ trợ.','[\"xin loi ban\", \"cho toi xin loi\", \"minh xin loi\", \"thanh that xin loi\"]',1,1,5,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(7,'social','Bạn giỏi quá','bạn giỏi quá','Dạ, cảm ơn anh/chị đã động viên ạ. Tôi sẽ cố gắng hỗ trợ anh/chị tốt nhất trong phạm vi thông tin của Cổng thông tin.','[\"ban gioi qua\", \"hay\", \"hay qua\", \"tuyet\", \"tuyet voi\", \"lam tot lam\", \"gioi that\"]',1,1,6,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(8,'social','Trả lời chậm quá','trả lời chậm quá','Dạ, tôi xin lỗi nếu khiến anh/chị chờ ạ. Anh/chị vui lòng nhắn lại câu hỏi, tôi sẽ hỗ trợ ngay.','[\"tra loi cham qua\", \"sao lau the\", \"phan hoi cham\", \"lau qua vay\"]',1,1,7,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(9,'social','Ừ được','ừ được','Dạ vâng ạ. Anh/chị cứ nhắn nếu cần tôi tra cứu thêm thông tin.','[\"duoc\", \"duoc roi\", \"oke\", \"okey\", \"vang a\"]',1,1,8,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(10,'social','Ok','ok','Dạ vâng ạ. Anh/chị cần hỏi thêm gì cứ nhắn cho tôi nhé.','[\"ok\", \"okay\", \"uh\", \"um\", \"roi\"]',1,1,9,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(11,'social','Hiểu rồi','hiểu rồi','Dạ vâng, anh/chị đã nắm được thông tin ạ. Khi cần thêm, anh/chị cứ nhắn cho tôi.','[\"hieu roi\", \"biet roi\", \"ro roi\", \"nam duoc roi\"]',1,1,10,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(12,'social','Bạn có khỏe không','bạn có khỏe không','Dạ cảm ơn anh/chị đã hỏi thăm, tôi luôn sẵn sàng hỗ trợ ạ. Anh/chị cần tôi giúp thông tin gì hôm nay?','[\"ban co khoe khong\", \"ban khoe khong\", \"khoe khong\", \"ban on khong\"]',1,1,11,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(13,'social','Chúc bạn một ngày tốt lành','chúc bạn một ngày tốt lành','Dạ, cảm ơn anh/chị. Kính chúc anh/chị sức khỏe và mọi việc thuận lợi ạ.','[\"chuc mot ngay tot lanh\", \"chuc ban vui ve\", \"chuc buoi sang vui\", \"chuc ban may man\"]',1,1,12,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(14,'social','Bạn đang làm gì đấy','bạn đang làm gì đấy','Dạ tôi đang trực để hỗ trợ anh/chị đây ạ. Anh/chị cần tôi tra cứu thông tin gì về tái hòa nhập cộng đồng không?','[\"ban dang lam gi\", \"dang lam gi do\", \"ban ban khong\", \"the nao roi\"]',1,1,13,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(15,'social','Chào bạn nhé','chào bạn nhé','Dạ, kính chào anh/chị. Tôi là Trợ lý ảo Hướng Thiện, rất vui được hỗ trợ anh/chị. Anh/chị cần tôi giúp gì ạ?','[\"chao nhe\", \"chao em nhe\", \"hello ban\", \"chao tro ly\"]',1,1,14,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(16,'social','Nhờ bạn giúp một chút','nhờ bạn giúp một chút','Dạ vâng, anh/chị cứ nêu câu hỏi hoặc điều cần hỗ trợ, tôi sẽ tra cứu và hướng dẫn trong phạm vi thông tin của Cổng ạ.','[\"nho ban giup\", \"giup toi voi\", \"ban giup toi nhe\", \"lam on giup toi\"]',1,1,15,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(17,'social','Cảm ơn bạn rất nhiều','cảm ơn bạn rất nhiều','Dạ, được hỗ trợ anh/chị là niềm vui của tôi ạ. Khi cần thêm thông tin, anh/chị cứ nhắn cho tôi nhé.','[\"cam on rat nhieu\", \"cam on ban rat nhieu\", \"that biet on\", \"cam on da giup\"]',1,1,16,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(18,'social','Bạn dễ thương quá','bạn dễ thương quá','Dạ, cảm ơn anh/chị đã dành lời khen ạ. Tôi luôn cố gắng hỗ trợ anh/chị chu đáo trong phạm vi thông tin của Cổng.','[\"ban de thuong qua\", \"de thuong ghe\", \"ban that tot\", \"ban tot qua\"]',1,1,17,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(19,'social','Chúc bạn buổi tối vui vẻ','chúc bạn buổi tối vui vẻ','Dạ, cảm ơn anh/chị. Kính chúc anh/chị buổi tối an lành. Khi cần hỗ trợ, anh/chị cứ quay lại nhắn cho tôi ạ.','[\"chuc buoi toi vui ve\", \"chuc ngu ngon\", \"chuc toi vui\", \"chuc buoi chieu vui\"]',1,1,18,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(20,'social','Không có gì đâu','không có gì đâu','Dạ vâng ạ. Khi nào cần, anh/chị cứ nhắn cho tôi, tôi luôn sẵn sàng hỗ trợ.','[\"khong co gi dau\", \"khong sao dau\", \"de sau cung duoc\", \"thoi khong can dau\"]',1,1,19,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(21,'social','Bạn nói lại giúp tôi','bạn nói lại giúp tôi','Dạ vâng, anh/chị vui lòng cho tôi biết nội dung cần nhắc lại, hoặc nêu lại câu hỏi để tôi hỗ trợ chính xác hơn ạ.','[\"noi lai giup toi\", \"nhac lai giup\", \"ban noi lai di\", \"lap lai giup toi\"]',1,1,20,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(22,'social','Ừ','ừ','Dạ vâng ạ. Anh/chị cần hỏi thêm gì cứ nhắn cho tôi nhé.','[\"u\", \"uhm\", \"oke ban\", \"the a\", \"vay a\"]',1,1,21,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(23,'social','Chào lại nhé','chào lại nhé','Dạ, rất vui được gặp lại anh/chị. Anh/chị cần tôi hỗ trợ thông tin gì hôm nay ạ?','[\"chao lai\", \"lai la toi day\", \"toi lai den day\", \"gap lai ban\"]',1,1,22,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(24,'social','Bạn làm phiền tôi quá','bạn làm phiền tôi quá','Dạ, tôi xin lỗi nếu khiến anh/chị chưa hài lòng ạ. Anh/chị cứ cho tôi biết cần hỗ trợ điều gì để tôi giúp đúng hơn.','[\"ban lam phien qua\", \"phien qua di\", \"dung lam phien toi\", \"kho chiu qua\"]',1,1,23,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(25,'social','Bạn thật đáng tin','bạn thật đáng tin','Dạ, cảm ơn anh/chị đã tin tưởng. Tôi luôn trả lời dựa trên thông tin đã được phê duyệt của Cổng thông tin ạ.','[\"ban that dang tin\", \"tin tuong ban\", \"ban dang tin cay\", \"toi tin ban\"]',1,1,24,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(26,'social','Vâng ạ','vâng ạ','Dạ vâng ạ. Khi cần thêm thông tin, anh/chị cứ nhắn cho tôi nhé.','[\"vang\", \"da vang\", \"da\", \"vang toi hieu\"]',1,1,25,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(27,'social','Tốt','tốt','Dạ, em cảm ơn anh/chị ạ. Anh/chị cần tôi hỗ trợ thêm điều gì không?','[\"tot\", \"tot qua\", \"qua tuyet\", \"hay day\"]',1,1,26,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(28,'social','Cho tôi hỏi chút','cho tôi hỏi chút','Dạ vâng, anh/chị cứ nêu câu hỏi, tôi sẽ tra cứu và hỗ trợ trong phạm vi thông tin của Cổng thông tin ạ.','[\"cho toi hoi chut\", \"hoi ti duoc khong\", \"cho hoi mot chut\", \"toi muon hoi\"]',1,1,27,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(29,'social','Bạn còn đó không','bạn còn đó không','Dạ tôi vẫn ở đây ạ. Anh/chị cứ tiếp tục nhắn câu hỏi cho tôi nhé.','[\"ban con do khong\", \"con day khong\", \"ban di dau roi\", \"van con nghe khong\"]',1,1,28,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(30,'social','Cảm ơn đã lắng nghe','cảm ơn đã lắng nghe','Dạ, được lắng nghe và hỗ trợ anh/chị là điều tôi luôn sẵn lòng. Anh/chị cần thêm gì cứ nhắn cho tôi nhé.','[\"cam on da lang nghe\", \"cam on vi da nghe\", \"cam on da chia se\", \"cam on su giup do\"]',1,1,29,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(31,'social','Chào buổi trưa','chào buổi trưa','Dạ, kính chào anh/chị. Chúc anh/chị buổi trưa an lành. Anh/chị cần tôi hỗ trợ thông tin gì ạ?','[\"chao buoi trua\", \"trua vui ve\", \"chuc buoi trua\", \"an trua ngon mieng\"]',1,1,30,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(32,'social','Tôi hơi bực','tôi hơi bực','Dạ, tôi xin lỗi nếu có điều gì khiến anh/chị chưa hài lòng ạ. Anh/chị cứ cho tôi biết cần hỗ trợ gì để tôi giúp tốt hơn.','[\"toi hoi buc\", \"buc minh qua\", \"toi kho chiu\", \"toi thay phien\"]',1,1,31,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(33,'identity','Bạn là ai','bạn là ai','Dạ, tôi là Trợ lý ảo Hướng Thiện của Cổng thông tin Con Đường Hướng Thiện. Tôi hỗ trợ thông tin về tái hòa nhập cộng đồng cho người hoàn lương ạ.','[\"ban la ai\", \"em la ai\", \"ai day\", \"ai do vay\"]',1,1,32,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(34,'identity','Bạn tên là gì','bạn tên là gì','Dạ, tôi là Trợ lý ảo Hướng Thiện. Anh/chị cứ gọi tôi để được hỗ trợ tra cứu thông tin của Cổng thông tin nhé.','[\"ban ten gi\", \"ban ten la gi\", \"ten ban la gi\", \"cho hoi ten ban\"]',1,1,33,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(35,'identity','Bạn có phải người thật không','bạn có phải người thật không','Dạ, tôi là trợ lý tự động, không phải người thật ạ. Tôi trả lời dựa trên kho dữ liệu đã được Cục C11 phê duyệt. Khi cần gặp cán bộ, tôi sẽ hướng dẫn anh/chị để lại thông tin liên hệ.','[\"ban la nguoi that khong\", \"ban co phai nguoi khong\", \"la nguoi hay may\", \"ban la nguoi hay robot\"]',1,1,34,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(36,'identity','Bạn là con gì','bạn là con gì','Dạ, tôi là trợ lý ảo của Cổng thông tin Con Đường Hướng Thiện, hoạt động tự động để hỗ trợ anh/chị tra cứu thông tin ạ.','[\"ban la con gi\", \"ban la cai gi\", \"ban la bot gi\", \"ban la ung dung gi\"]',1,1,35,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(37,'identity','Bạn làm được gì','bạn làm được gì','Dạ, tôi giúp anh/chị tra cứu thông tin về thủ tục xóa án tích, vay vốn, đăng ký cư trú, hỗ trợ học nghề - tìm việc làm, và các mô hình tái hòa nhập cộng đồng đã được đăng trên Cổng thông tin.','[\"ban lam duoc gi\", \"ban co the lam gi\", \"lam duoc nhung gi\", \"ban giup duoc gi\"]',1,1,36,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(38,'identity','Bạn hỗ trợ những gì','bạn hỗ trợ những gì','Dạ, tôi hỗ trợ giải đáp theo kho dữ liệu đã được phê duyệt của Cổng thông tin. Nếu câu hỏi vượt ngoài phạm vi, tôi sẽ xin thông tin liên hệ để cán bộ phản hồi trực tiếp ạ.','[\"ban ho tro gi\", \"ho tro nhung gi\", \"ban tu van gi\", \"giup gi cho toi\"]',1,1,37,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(39,'identity','Bạn biết những gì','bạn biết những gì','Dạ, tôi nắm các thông tin đã được đăng và phê duyệt trên Cổng thông tin về tái hòa nhập cộng đồng. Anh/chị cứ nêu câu hỏi cụ thể, tôi sẽ tra cứu giúp ạ.','[\"ban biet gi\", \"ban biet nhung gi\", \"ban co biet nhieu khong\", \"ban nam duoc gi\"]',1,1,38,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(40,'identity','Tôi có thể hỏi bạn những gì','tôi có thể hỏi bạn những gì','Dạ, anh/chị có thể hỏi tôi về: thủ tục xóa án tích, vay vốn cho người hoàn lương, đăng ký thường trú/tạm trú, hỗ trợ học nghề - tìm việc làm, hoặc các mô hình tái hòa nhập cộng đồng.','[\"co the hoi gi\", \"toi hoi duoc gi\", \"hoi ban duoc nhung gi\", \"nen hoi gi\"]',1,1,39,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(41,'identity','Bạn có thông minh không','bạn có thông minh không','Dạ, tôi cố gắng trả lời chính xác theo kho dữ liệu đã được phê duyệt. Nếu chưa có thông tin phù hợp, tôi sẽ nói rõ và hướng dẫn anh/chị liên hệ cán bộ ạ.','[\"ban co thong minh khong\", \"ban co gioi khong\", \"ban co hieu toi khong\", \"ban tra loi dung khong\"]',1,1,40,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(42,'identity','Ai tạo ra bạn','ai tạo ra bạn','Dạ, tôi là trợ lý ảo của Cổng thông tin Con Đường Hướng Thiện, do Cục Cảnh sát quản lý tạm giữ, tạm giam và thi hành án hình sự tại cộng đồng (C11) - Bộ Công an chủ quản.','[\"ai tao ra ban\", \"ai lam ra ban\", \"ban cua don vi nao\", \"ai quan ly ban\"]',1,1,41,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(43,'identity','Bạn có mất tiền không','bạn có mất tiền không','Dạ, việc hỏi đáp với tôi trên Cổng thông tin là hoàn toàn miễn phí ạ. Anh/chị cứ thoải mái nhắn câu hỏi.','[\"ban co mat tien khong\", \"dung ban co ton phi khong\", \"hoi ban co mat phi khong\"]',1,1,42,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(44,'identity','Bạn có nói chuyện được không','bạn có nói chuyện được không','Dạ được ạ. Anh/chị cứ nhắn câu hỏi bằng tiếng Việt, tôi sẽ tra cứu và trả lời trong phạm vi thông tin của Cổng thông tin.','[\"ban noi chuyen duoc khong\", \"ban chat duoc khong\", \"ban tra loi duoc khong\", \"ban nghe toi khong\"]',1,1,43,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(45,'identity','Bạn có hiểu tiếng Việt không','bạn có hiểu tiếng việt không','Dạ, tôi hỗ trợ bằng tiếng Việt ạ. Anh/chị cứ nêu câu hỏi, tôi sẽ cố gắng giải đáp.','[\"ban hieu tieng viet khong\", \"ban noi tieng viet khong\", \"dung tieng viet duoc khong\", \"ho tro tieng viet khong\"]',1,1,44,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(46,'identity','Bạn làm việc cho ai','bạn làm việc cho ai','Dạ, tôi là trợ lý ảo của Cổng thông tin Con Đường Hướng Thiện, phục vụ người dân, đặc biệt là người hoàn lương, do Cục C11 - Bộ Công an chủ quản ạ.','[\"ban lam viec cho ai\", \"ban thuoc don vi nao\", \"ban dai dien cho ai\", \"ban phuc vu ai\"]',1,1,45,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(47,'identity','Bạn có thay được cán bộ không','bạn có thay được cán bộ không','Dạ, tôi chỉ hỗ trợ tra cứu và cung cấp thông tin, không thay thế cán bộ trong việc giải quyết hồ sơ. Khi cần, tôi sẽ hướng dẫn anh/chị để lại thông tin liên hệ để cán bộ hỗ trợ trực tiếp.','[\"ban thay duoc can bo khong\", \"ban co phai can bo khong\", \"ban co quyet dinh duoc khong\", \"ban giai quyet duoc khong\"]',1,1,46,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(48,'identity','Bạn trả lời dựa vào đâu','bạn trả lời dựa vào đâu','Dạ, tôi trả lời dựa trên kho dữ liệu đã được Cục C11 phê duyệt và đăng trên Cổng thông tin. Nếu chưa có nội dung phù hợp, tôi sẽ nói rõ và hướng dẫn anh/chị liên hệ cán bộ.','[\"ban tra loi dua vao dau\", \"thong tin ban lay tu dau\", \"ban lay du lieu o dau\", \"nguon thong tin cua ban\"]',1,1,47,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(49,'identity','Bạn có ghi nhớ cuộc trò chuyện không','bạn có ghi nhớ cuộc trò chuyện không','Dạ, tôi hỗ trợ trả lời câu hỏi ngay trong phiên trò chuyện. Với thông tin liên hệ anh/chị để lại, hệ thống lưu để cán bộ phản hồi và được bảo vệ theo quy định.','[\"ban co ghi nho khong\", \"ban co luu cuoc tro chuyen khong\", \"ban nho toi khong\", \"ban luu lich su khong\"]',1,1,48,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(50,'identity','Bạn hoạt động thế nào','bạn hoạt động thế nào','Dạ, tôi nhận câu hỏi của anh/chị, tra cứu trong kho dữ liệu đã được phê duyệt của Cổng thông tin và trả lời. Nếu chưa có nội dung phù hợp, tôi hướng dẫn anh/chị liên hệ cán bộ ạ.','[\"ban hoat dong the nao\", \"ban lam viec ra sao\", \"ban van hanh the nao\", \"ban tra loi kieu gi\"]',1,1,49,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(51,'identity','Bạn có online suốt không','bạn có online suốt không','Dạ, tôi trực hỗ trợ tra cứu thông tin liên tục để anh/chị có thể hỏi bất cứ lúc nào ạ.','[\"ban co online suot khong\", \"ban truc suot khong\", \"luc nao cung co ban khong\", \"ban co nghi khong\"]',1,1,50,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(52,'identity','Bạn nói được mấy thứ tiếng','bạn nói được mấy thứ tiếng','Dạ, hiện tôi hỗ trợ chủ yếu bằng tiếng Việt, phù hợp với nội dung của Cổng thông tin ạ.','[\"ban noi may thu tieng\", \"ban biet ngoai ngu khong\", \"ban co tieng anh khong\", \"ban dung ngon ngu nao\"]',1,1,51,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(53,'identity','Bạn có tính phí tư vấn không','bạn có tính phí tư vấn không','Dạ, việc hỏi đáp và tra cứu thông tin với tôi trên Cổng thông tin là miễn phí ạ.','[\"ban co tinh phi tu van khong\", \"tu van co mat tien khong\", \"hoi ban co tra phi khong\", \"tu van voi ban co phi khong\"]',1,1,52,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(54,'identity','Chào bot','chào bot','Dạ, tôi là Trợ lý ảo Hướng Thiện đây ạ. Anh/chị cần tôi hỗ trợ thông tin gì không?','[\"chao bot oi\", \"bot oi\", \"tro ly oi\", \"bot gi day\"]',1,1,53,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(55,'identity','Bạn có tư vấn pháp luật được không','bạn có tư vấn pháp luật được không','Dạ, tôi cung cấp thông tin đã được đăng và phê duyệt trên Cổng thông tin để anh/chị tham khảo, không thay cho tư vấn pháp lý cho trường hợp cụ thể. Khi cần, tôi sẽ hướng dẫn anh/chị liên hệ cán bộ.','[\"ban tu van phap luat duoc khong\", \"ban co tra loi phap luat khong\", \"ban giai dap luat khong\", \"hoi luat duoc khong\"]',1,1,54,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(56,'identity','Bạn tên đầy đủ là gì','bạn tên đầy đủ là gì','Dạ, tôi là Trợ lý ảo Hướng Thiện của Cổng thông tin Con Đường Hướng Thiện ạ. Anh/chị cứ gọi tôi để được hỗ trợ nhé.','[\"ten day du cua ban\", \"ban ten chinh thuc la gi\", \"goi ban la gi cho dung\", \"ten goi cua ban\"]',1,1,55,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(57,'navigation','Trang này có gì','trang này có gì','Dạ, Cổng thông tin có các mục chính: Tin tức, Tấm gương hoàn lương, Mô hình tái hòa nhập cộng đồng, Văn bản pháp luật, Giải đáp pháp luật, và mục Đăng ký tư vấn. Anh/chị muốn xem mục nào ạ? Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"trang nay co gi\", \"cong nay co gi\", \"website co gi\", \"o day co gi\"]',1,1,56,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(58,'navigation','Tìm văn bản pháp luật ở đâu','tìm văn bản pháp luật ở đâu','Dạ, anh/chị vào mục \"Văn bản\" trên thanh điều hướng của Cổng thông tin để xem các văn bản quy phạm pháp luật đã đăng ạ. Anh/chị cần tìm nội dung cụ thể nào, tôi có thể tra giúp.','[\"tim van ban o dau\", \"van ban phap luat o dau\", \"xem van ban o dau\", \"muc van ban o dau\"]',1,1,57,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(59,'navigation','Xem tin tức ở đâu','xem tin tức ở đâu','Dạ, anh/chị vào mục \"Tin tức\" trên Cổng thông tin để đọc tin địa phương, tin hoạt động và bản tin nổi bật ạ.','[\"xem tin tuc o dau\", \"muc tin tuc o dau\", \"doc tin tuc cho nao\", \"tin tuc nam o dau\"]',1,1,58,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(60,'navigation','Xem tấm gương hoàn lương ở đâu','xem tấm gương hoàn lương ở đâu','Dạ, anh/chị vào mục \"Tấm gương hoàn lương\" trên Cổng thông tin để xem các câu chuyện tái hòa nhập tiêu biểu ạ.','[\"xem tam guong o dau\", \"tam guong hoan luong o dau\", \"guong nguoi tot o dau\", \"muc tam guong cho nao\"]',1,1,59,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(61,'navigation','Xem mô hình tái hòa nhập ở đâu','xem mô hình tái hòa nhập ở đâu','Dạ, anh/chị vào mục \"Mô hình tái hòa nhập cộng đồng\" trên Cổng thông tin để tham khảo các mô hình đang triển khai ạ.','[\"xem mo hinh o dau\", \"mo hinh tai hoa nhap o dau\", \"muc mo hinh cho nao\", \"tim mo hinh o dau\"]',1,1,60,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(62,'navigation','Đăng ký tư vấn như thế nào','đăng ký tư vấn như thế nào','Dạ, anh/chị vào mục \"Liên hệ\" hoặc \"Đăng ký tư vấn\" trên Cổng thông tin, để lại họ tên và số điện thoại, cán bộ sẽ liên hệ hỗ trợ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"dang ky tu van the nao\", \"cach dang ky tu van\", \"muon duoc tu van\", \"lam sao de duoc tu van\"]',1,1,61,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(63,'navigation','Giải đáp pháp luật ở mục nào','giải đáp pháp luật ở mục nào','Dạ, anh/chị vào mục \"Giải đáp pháp luật\" trên Cổng thông tin để xem các câu hỏi thường gặp đã được giải đáp ạ. Anh/chị cũng có thể nêu câu hỏi trực tiếp cho tôi.','[\"giai dap phap luat o dau\", \"hoi dap phap luat o dau\", \"muc hoi dap cho nao\", \"phan giai dap o dau\"]',1,1,62,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(64,'navigation','Trang giới thiệu ở đâu','trang giới thiệu ở đâu','Dạ, anh/chị vào mục \"Giới thiệu\" trên Cổng thông tin để xem thông tin về đơn vị chủ quản và mục đích của Cổng ạ.','[\"trang gioi thieu o dau\", \"muc gioi thieu cho nao\", \"thong tin ve cong o dau\", \"ve chung toi o dau\"]',1,1,63,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(65,'navigation','Làm sao để tìm thông tin trên trang','làm sao để tìm thông tin trên trang','Dạ, anh/chị có thể dùng thanh điều hướng theo từng mục, hoặc nêu câu hỏi trực tiếp cho tôi, tôi sẽ tra cứu giúp trong kho dữ liệu đã được phê duyệt. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"lam sao tim thong tin\", \"cach tim kiem tren trang\", \"tim kiem o dau\", \"tim thong tin the nao\"]',1,1,64,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(66,'navigation','Liên hệ với cán bộ ở đâu','liên hệ với cán bộ ở đâu','Dạ, anh/chị vào mục \"Liên hệ\" trên Cổng thông tin để lại thông tin, cán bộ sẽ phản hồi. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"lien he can bo o dau\", \"gap can bo the nao\", \"muon gap can bo\", \"lien he truc tiep o dau\"]',1,1,65,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(67,'navigation','Xem thông tin vay vốn ở đâu','xem thông tin vay vốn ở đâu','Dạ, anh/chị có thể tra cứu thông tin về vay vốn cho người hoàn lương trong mục Giải đáp pháp luật và Tin tức của Cổng, hoặc nêu câu hỏi cụ thể để tôi tra giúp. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"xem vay von o dau\", \"thong tin vay von cho nao\", \"muc vay von o dau\", \"tim thong tin vay von\"]',1,1,66,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(68,'navigation','Thông tin học nghề tìm việc ở đâu','thông tin học nghề tìm việc ở đâu','Dạ, anh/chị tham khảo thông tin hỗ trợ học nghề - tìm việc làm trong mục Tin tức và các mô hình tái hòa nhập trên Cổng. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"thong tin hoc nghe o dau\", \"tim viec lam o dau\", \"ho tro viec lam cho nao\", \"muc hoc nghe o dau\"]',1,1,67,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(69,'navigation','Cách quay lại trang chủ','cách quay lại trang chủ','Dạ, anh/chị bấm vào biểu tượng hoặc tên Cổng thông tin ở đầu trang để quay về trang chủ ạ.','[\"cach ve trang chu\", \"quay lai trang chu the nao\", \"ve trang chinh o dau\", \"tro ve trang dau\"]',1,1,68,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(70,'navigation','Xem số điện thoại liên hệ ở đâu','xem số điện thoại liên hệ ở đâu','Dạ, thông tin liên hệ có ở mục \"Liên hệ\" trên Cổng thông tin. Anh/chị cũng có thể gọi đường dây nóng 0903.480.985 để được hỗ trợ.','[\"xem so dien thoai o dau\", \"so lien he o dau\", \"tim so dien thoai cho nao\", \"thong tin lien he o dau\"]',1,1,69,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(71,'navigation','Đổi ngôn ngữ ở đâu','đổi ngôn ngữ ở đâu','Dạ, nút chuyển đổi ngôn ngữ nằm ở thanh trên cùng của Cổng thông tin ạ. Hiện nội dung chủ yếu phục vụ bằng tiếng Việt.','[\"doi ngon ngu o dau\", \"chuyen tieng anh o dau\", \"thay doi ngon ngu the nao\", \"nut doi ngon ngu cho nao\"]',1,1,70,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(72,'navigation','Chỉnh cỡ chữ ở đâu','chỉnh cỡ chữ ở đâu','Dạ, anh/chị dùng các nút A-, A, A+ ở thanh trên cùng của Cổng thông tin để điều chỉnh cỡ chữ cho dễ đọc ạ.','[\"chinh co chu o dau\", \"phong to chu the nao\", \"tang co chu o dau\", \"thay doi co chu cho nao\"]',1,1,71,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(73,'navigation','Xem thủ tục xóa án tích ở mục nào','xem thủ tục xóa án tích ở mục nào','Dạ, anh/chị có thể tìm nội dung liên quan trong mục Giải đáp pháp luật và Văn bản trên Cổng, hoặc nêu câu hỏi cụ thể để tôi tra giúp. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"xem thu tuc xoa an tich o dau\", \"muc xoa an tich cho nao\", \"tim thong tin xoa an tich\", \"thong tin an tich o dau\"]',1,1,72,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(74,'navigation','Xem thông tin đăng ký cư trú ở đâu','xem thông tin đăng ký cư trú ở đâu','Dạ, anh/chị tham khảo mục Giải đáp pháp luật và Văn bản trên Cổng để tìm thông tin về đăng ký thường trú/tạm trú, hoặc nêu câu hỏi để tôi hỗ trợ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"thong tin dang ky cu tru o dau\", \"muc cu tru cho nao\", \"dang ky thuong tru o dau\", \"tim thong tin tam tru\"]',1,1,73,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(75,'navigation','Tải văn bản về máy như thế nào','tải văn bản về máy như thế nào','Dạ, trong mục Văn bản, anh/chị mở văn bản cần xem, thường có liên kết để tải tệp về máy ạ. Nếu gặp khó, anh/chị cứ nhắn tôi hỗ trợ.','[\"tai van ban ve may\", \"download van ban the nao\", \"lay file van ban o dau\", \"tai tai lieu the nao\"]',1,1,74,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(76,'navigation','Nút hỗ trợ 24/7 ở đâu','nút hỗ trợ 24/7 ở đâu','Dạ, nút hỗ trợ và khung trò chuyện với tôi thường ở góc màn hình của Cổng thông tin. Anh/chị cũng có thể gọi đường dây nóng 0903.480.985.','[\"nut ho tro o dau\", \"ho tro 24 7 cho nao\", \"nut tro giup o dau\", \"goi ho tro nhanh o dau\"]',1,1,75,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(77,'navigation','Xem tin nổi bật ở đâu','xem tin nổi bật ở đâu','Dạ, anh/chị vào mục Tin tức trên Cổng, ở đó có tin nổi bật, tin hoạt động và tin địa phương để anh/chị theo dõi ạ.','[\"xem tin noi bat o dau\", \"tin noi bat cho nao\", \"muc tin hoat dong o dau\", \"tin dia phuong o dau\"]',1,1,76,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(78,'navigation','Trang bị lỗi thì làm sao','trang bị lỗi thì làm sao','Dạ, anh/chị thử tải lại trang hoặc mở bằng trình duyệt khác giúp tôi ạ. Nếu vẫn chưa được, anh/chị gọi đường dây nóng 0903.480.985 để được hỗ trợ.','[\"trang bi loi lam sao\", \"website loi thi sao\", \"khong vao duoc trang\", \"trang khong hien thi\"]',1,1,77,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(79,'navigation','Tìm câu hỏi thường gặp ở đâu','tìm câu hỏi thường gặp ở đâu','Dạ, anh/chị vào mục Giải đáp pháp luật trên Cổng để xem các câu hỏi thường gặp đã được giải đáp ạ. Anh/chị cũng có thể hỏi trực tiếp tôi.','[\"cau hoi thuong gap o dau\", \"muc faq cho nao\", \"xem cac cau hoi pho bien\", \"tim cau hoi hay gap\"]',1,1,78,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(80,'support','Tôi mới ra tù tôi lo lắm','tôi mới ra tù tôi lo lắm','Dạ, tôi hiểu đây là giai đoạn có nhiều điều khiến anh/chị băn khoăn. Cổng thông tin có các thông tin về hỗ trợ vay vốn, học nghề, việc làm và đăng ký cư trú để anh/chị tham khảo từng bước một. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi moi ra tu\", \"moi ra tu lo lam\", \"ra tu khong biet lam gi\", \"moi chap hanh xong an\"]',1,1,79,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(81,'support','Tôi thấy bế tắc','tôi thấy bế tắc','Dạ, tôi ghi nhận điều anh/chị đang trải qua. Anh/chị không phải đối mặt một mình đâu ạ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi thay be tac\", \"toi be tac qua\", \"khong loi thoat\", \"toi thay tuyet vong\"]',1,1,80,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(82,'support','Không ai nhận tôi vào làm','không ai nhận tôi vào làm','Dạ, tôi hiểu việc tìm công việc lúc này không dễ. Cổng thông tin có mục hỗ trợ học nghề - tìm việc làm và các mô hình tái hòa nhập để anh/chị tham khảo. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"khong ai nhan toi vao lam\", \"khong xin duoc viec\", \"khong ai thue toi\", \"kho tim viec qua\"]',1,1,81,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(83,'support','Tôi bị mọi người xa lánh','tôi bị mọi người xa lánh','Dạ, tôi rất chia sẻ với cảm giác của anh/chị. Anh/chị xứng đáng được hỗ trợ để hòa nhập trở lại. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi bi xa lanh\", \"moi nguoi xa lanh toi\", \"bi ky thi\", \"khong ai gan gui toi\"]',1,1,82,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(84,'support','Tôi không biết bắt đầu từ đâu','tôi không biết bắt đầu từ đâu','Dạ, anh/chị có thể bắt đầu bằng việc ổn định nơi cư trú và tìm hiểu các chương trình hỗ trợ trên Cổng thông tin, như vay vốn, học nghề và việc làm. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"khong biet bat dau tu dau\", \"bat dau lai the nao\", \"khong biet lam gi truoc\", \"nen lam gi dau tien\"]',1,1,83,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(85,'support','Tôi lo không hòa nhập được','tôi lo không hòa nhập được','Dạ, cảm giác lo lắng lúc này là điều dễ hiểu. Cổng thông tin có nhiều tấm gương và mô hình tái hòa nhập để anh/chị tham khảo và thêm động lực. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"lo khong hoa nhap duoc\", \"so khong hoa nhap\", \"kho hoa nhap cong dong\", \"lo khong tai hoa nhap duoc\"]',1,1,84,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(86,'support','Tôi buồn quá','tôi buồn quá','Dạ, tôi ghi nhận điều anh/chị đang cảm thấy. Khi cần người lắng nghe và hướng dẫn cụ thể, anh/chị đừng ngần ngại tìm đến sự hỗ trợ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi buon qua\", \"toi thay buon\", \"trong long nang ne\", \"toi met moi qua\"]',1,1,85,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(87,'support','Gia đình không tin tưởng tôi nữa','gia đình không tin tưởng tôi nữa','Dạ, tôi hiểu điều này khiến anh/chị tổn thương. Việc từng bước ổn định cuộc sống có thể giúp xây dựng lại niềm tin. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"gia dinh khong tin toi\", \"nguoi than xa lanh\", \"gia dinh khong chap nhan\", \"khong ai tin toi\"]',1,1,86,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(88,'support','Tôi sợ bị kỳ thị khi đi xin việc','tôi sợ bị kỳ thị khi đi xin việc','Dạ, tôi hiểu nỗi lo của anh/chị. Anh/chị có thể tham khảo mục hỗ trợ việc làm và các mô hình tái hòa nhập trên Cổng thông tin. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"so bi ky thi khi xin viec\", \"so bi phan biet\", \"ngai di xin viec\", \"so nguoi ta biet qua khu\"]',1,1,87,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(89,'support','Tôi muốn làm lại từ đầu','tôi muốn làm lại từ đầu','Dạ, mong muốn làm lại của anh/chị rất đáng trân trọng. Cổng thông tin có các thông tin về vay vốn, học nghề, việc làm để anh/chị tham khảo cho hành trình sắp tới. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi muon lam lai tu dau\", \"muon lam lai cuoc doi\", \"muon bat dau lai\", \"muon huong thien\"]',1,1,88,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(90,'support','Tôi thấy có lỗi với gia đình','tôi thấy có lỗi với gia đình','Dạ, tôi ghi nhận điều anh/chị đang suy nghĩ. Từng bước ổn định cuộc sống là điều anh/chị có thể bắt đầu ngay hôm nay. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi thay co loi voi gia dinh\", \"an han voi nguoi than\", \"toi hoi han lam\", \"toi thay co loi\"]',1,1,89,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(91,'support','Tôi sợ tái phạm','tôi sợ tái phạm','Dạ, việc anh/chị nghĩ đến điều này cho thấy mong muốn hướng thiện. Anh/chị có thể tìm đến các chương trình hỗ trợ để có thêm điểm tựa. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi so tai pham\", \"so quay lai duong cu\", \"lo lam lai chuyen xau\", \"so khong giu duoc minh\"]',1,1,90,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(92,'support','Tôi không có tiền để bắt đầu','tôi không có tiền để bắt đầu','Dạ, tôi hiểu khó khăn về tài chính lúc này. Cổng thông tin có thông tin về chương trình vay vốn cho người hoàn lương để anh/chị tham khảo. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"khong co tien de bat dau\", \"khong co von\", \"thieu tien lam an\", \"khong du tien sinh song\"]',1,1,91,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(93,'support','Tôi thấy mình vô dụng','tôi thấy mình vô dụng','Dạ, tôi không nghĩ như vậy đâu ạ. Mỗi người đều có thể bắt đầu lại và đóng góp cho cộng đồng. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi thay minh vo dung\", \"toi vo dung qua\", \"toi khong lam duoc gi\", \"toi thay minh kem coi\"]',1,1,92,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(94,'support','Tôi cô đơn quá','tôi cô đơn quá','Dạ, tôi ghi nhận điều anh/chị đang trải qua. Anh/chị không đơn độc, luôn có nơi sẵn sàng hỗ trợ anh/chị. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi co don qua\", \"toi thay co doc\", \"khong co ai ben canh\", \"toi mot minh\"]',1,1,93,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(95,'support','Tôi mất niềm tin vào bản thân','tôi mất niềm tin vào bản thân','Dạ, tôi ghi nhận điều anh/chị đang cảm thấy. Từng bước nhỏ hôm nay cũng là tiến bộ đáng ghi nhận. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi mat niem tin\", \"khong tin vao ban than\", \"toi khong con dong luc\", \"toi chan nan\"]',1,1,94,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(96,'support','Tôi bị hàng xóm dị nghị','tôi bị hàng xóm dị nghị','Dạ, tôi hiểu điều này khiến anh/chị không thoải mái. Việc ổn định cuộc sống và tham gia các hoạt động cộng đồng có thể giúp ích dần. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"bi hang xom di nghi\", \"hang xom ban tan\", \"nguoi xung quanh soi moi\", \"bi noi ra noi vao\"]',1,1,95,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(97,'support','Tôi không biết tương lai sẽ ra sao','tôi không biết tương lai sẽ ra sao','Dạ, cảm giác lo cho ngày mai là điều dễ hiểu. Anh/chị có thể bắt đầu bằng những việc trong tầm tay và tham khảo thông tin hỗ trợ trên Cổng. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"khong biet tuong lai ra sao\", \"lo cho tuong lai\", \"tuong lai mo mit\", \"khong biet ngay mai the nao\"]',1,1,96,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(98,'support','Tôi cần người động viên','tôi cần người động viên','Dạ, tôi luôn sẵn sàng lắng nghe anh/chị trong phạm vi hỗ trợ của mình. Khi cần được đồng hành cụ thể hơn, anh/chị đừng ngần ngại tìm đến sự giúp đỡ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"toi can nguoi dong vien\", \"can ai do lang nghe\", \"muon co nguoi chia se\", \"can duoc an ui\"]',1,1,97,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(99,'support','Tôi mệt mỏi với cuộc sống hiện tại','tôi mệt mỏi với cuộc sống hiện tại','Dạ, tôi ghi nhận những khó khăn anh/chị đang gánh. Anh/chị có thể tìm hiểu các chương trình hỗ trợ trên Cổng để bớt phần vất vả. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"met moi voi cuoc song\", \"cuoc song qua kho khan\", \"toi kiet suc roi\", \"song met moi qua\"]',1,1,98,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(100,'support','Tôi muốn thay đổi nhưng khó quá','tôi muốn thay đổi nhưng khó quá','Dạ, mong muốn thay đổi của anh/chị rất đáng quý và những bước đầu thường là khó nhất. Anh/chị có thể tham khảo thông tin hỗ trợ trên Cổng để đi từng bước. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"muon thay doi nhung kho\", \"thay doi kho khan qua\", \"co gang ma van kho\", \"muon lam lai ma be tac\"]',1,1,99,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(101,'portal_facts','Dùng cổng có mất phí không','dùng cổng có mất phí không','Dạ, Cổng thông tin điện tử này phục vụ anh/chị hoàn toàn miễn phí ạ. Lưu ý rằng các thủ tục hành chính thực hiện bên ngoài Cổng có thể có quy định riêng của cơ quan tiếp nhận, anh/chị nên hỏi trực tiếp nơi làm thủ tục để rõ.','[\"dung cong co mat phi khong\", \"co mat phi khong\", \"co ton tien khong\", \"dich vu nay co mat phi khong\", \"su dung co tinh phi khong\"]',1,1,100,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(102,'portal_facts','Giờ làm việc thế nào','giờ làm việc thế nào','Dạ, tôi hỗ trợ tra cứu thông tin trên Cổng thông tin 24/7. Với việc gặp cán bộ trực tiếp, thời gian tiếp nhận theo giờ hành chính của cơ quan. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"gio lam viec the nao\", \"may gio lam viec\", \"lam viec luc nao\", \"gio hanh chinh the nao\"]',1,1,101,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(103,'portal_facts','Gọi hotline như thế nào','gọi hotline như thế nào','Dạ, anh/chị có thể gọi đường dây nóng 0903.480.985 để được hỗ trợ ạ.','[\"goi hotline the nao\", \"so hotline la gi\", \"duong day nong so may\", \"goi tong dai the nao\"]',1,1,102,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(104,'portal_facts','Thông tin của tôi có được bảo mật không','thông tin của tôi có được bảo mật không','Dạ, thông tin anh/chị để lại được sử dụng để cán bộ liên hệ hỗ trợ và được bảo vệ theo quy định. Anh/chị chỉ nên cung cấp thông tin cần thiết. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"thong tin co duoc bao mat khong\", \"co bao mat thong tin khong\", \"thong tin ca nhan co an toan khong\", \"du lieu cua toi co an toan khong\"]',1,1,103,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(105,'portal_facts','Cổng do đơn vị nào quản lý','cổng do đơn vị nào quản lý','Dạ, Cổng thông tin Con Đường Hướng Thiện do Cục Cảnh sát quản lý tạm giữ, tạm giam và thi hành án hình sự tại cộng đồng (C11) - Bộ Công an chủ quản ạ.','[\"cong do don vi nao quan ly\", \"ai quan ly cong nay\", \"don vi chu quan la ai\", \"cong cua co quan nao\"]',1,1,104,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(106,'portal_facts','Có ứng dụng điện thoại không','có ứng dụng điện thoại không','Dạ, hiện anh/chị truy cập Cổng thông tin qua trình duyệt web trên điện thoại hoặc máy tính ạ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"co ung dung dien thoai khong\", \"co app khong\", \"tai app o dau\", \"co phan mem dien thoai khong\"]',1,1,105,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(107,'portal_facts','Cổng thông tin này để làm gì','cổng thông tin này để làm gì','Dạ, Cổng thông tin hỗ trợ người hoàn lương tái hòa nhập cộng đồng, cung cấp thông tin về thủ tục, chính sách hỗ trợ, tấm gương và mô hình tái hòa nhập ạ.','[\"cong nay de lam gi\", \"muc dich cua cong\", \"cong lap ra de lam gi\", \"trang nay phuc vu ai\"]',1,1,106,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(108,'portal_facts','Tôi có cần đăng ký tài khoản không','tôi có cần đăng ký tài khoản không','Dạ, anh/chị có thể xem thông tin và hỏi đáp với tôi mà không cần đăng ký tài khoản ạ. Khi cần được tư vấn trực tiếp, anh/chị chỉ cần để lại thông tin liên hệ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"co can dang ky tai khoan khong\", \"phai tao tai khoan khong\", \"can dang nhap khong\", \"co phai lap tai khoan khong\"]',1,1,107,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(109,'portal_facts','Cổng có hỗ trợ ngoài giờ không','cổng có hỗ trợ ngoài giờ không','Dạ, tôi trực hỗ trợ tra cứu thông tin trên Cổng liên tục. Việc cán bộ phản hồi trực tiếp sẽ theo giờ làm việc của cơ quan. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"co ho tro ngoai gio khong\", \"toi khuya co ho tro khong\", \"ngoai gio co ai truc khong\", \"cuoi tuan co ho tro khong\"]',1,1,108,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(110,'portal_facts','Thông tin trên cổng có chính xác không','thông tin trên cổng có chính xác không','Dạ, tôi trả lời dựa trên kho dữ liệu đã được Cục C11 phê duyệt trên Cổng thông tin. Với trường hợp cụ thể của mình, anh/chị nên xác nhận thêm với cán bộ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"thong tin co chinh xac khong\", \"noi dung co dang tin khong\", \"thong tin co dung khong\", \"co dam bao chinh xac khong\"]',1,1,109,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(111,'portal_facts','Cổng có ở tỉnh thành nào','cổng có ở tỉnh thành nào','Dạ, Cổng thông tin phục vụ người dân trên phạm vi cả nước. Với thủ tục cụ thể tại địa phương, anh/chị liên hệ Công an xã/phường nơi cư trú, hoặc gọi đường dây nóng 0903.480.985.','[\"cong co o tinh nao\", \"phuc vu tinh thanh nao\", \"ap dung o dau\", \"co pham vi toan quoc khong\"]',1,1,110,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(112,'portal_facts','Ai được sử dụng cổng này','ai được sử dụng cổng này','Dạ, Cổng thông tin phục vụ mọi người dân quan tâm đến tái hòa nhập cộng đồng, đặc biệt là người hoàn lương và thân nhân. Anh/chị cứ thoải mái tra cứu ạ.','[\"ai duoc dung cong nay\", \"cong danh cho ai\", \"doi tuong su dung la ai\", \"toi co duoc dung khong\"]',1,1,111,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(113,'portal_facts','Cổng có thu thập thông tin gì của tôi không','cổng có thu thập thông tin gì của tôi không','Dạ, khi anh/chị đăng ký tư vấn, hệ thống chỉ lưu thông tin liên hệ cần thiết như họ tên và số điện thoại để cán bộ phản hồi. Anh/chị chỉ nên cung cấp thông tin cần thiết. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"cong thu thap thong tin gi\", \"lay thong tin gi cua toi\", \"can cung cap thong tin gi\", \"phai khai bao gi\"]',1,1,112,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(114,'portal_facts','Cổng hoạt động từ khi nào','cổng hoạt động từ khi nào','Dạ, Cổng thông tin là kênh hỗ trợ trực tuyến của Cục C11 - Bộ Công an. Để biết thêm chi tiết, anh/chị tham khảo mục Giới thiệu hoặc liên hệ đường dây nóng 0903.480.985.','[\"cong hoat dong tu khi nao\", \"cong co tu bao gio\", \"cong ra doi khi nao\", \"trang lap tu luc nao\"]',1,1,113,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(115,'portal_facts','Tôi muốn góp ý cho cổng','tôi muốn góp ý cho cổng','Dạ, anh/chị có thể gửi góp ý qua mục \"Liên hệ\" trên Cổng thông tin, hoặc gọi đường dây nóng 0903.480.985. Cảm ơn anh/chị đã quan tâm đóng góp ạ.','[\"toi muon gop y\", \"phan anh voi cong\", \"gui gop y o dau\", \"muon dong gop y kien\"]',1,1,114,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(116,'portal_facts','Cổng có hỗ trợ người thân của tôi không','cổng có hỗ trợ người thân của tôi không','Dạ, người thân của anh/chị hoàn toàn có thể tra cứu thông tin và đặt câu hỏi trên Cổng thông tin ạ. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"cong ho tro nguoi than khong\", \"gia dinh co dung duoc khong\", \"than nhan co tra cuu duoc khong\", \"nguoi nha co hoi duoc khong\"]',1,1,115,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(117,'portal_facts','Đăng ký tư vấn có tốn phí không','đăng ký tư vấn có tốn phí không','Dạ, việc đăng ký tư vấn và để lại thông tin liên hệ trên Cổng thông tin là miễn phí ạ. Các thủ tục hành chính bên ngoài Cổng có thể theo quy định riêng của cơ quan tiếp nhận.','[\"dang ky tu van co ton phi khong\", \"tu van co mat phi khong\", \"de lai thong tin co ton tien khong\", \"lien he can bo co mat phi khong\"]',1,1,116,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(118,'portal_facts','Tôi để lại thông tin thì bao giờ được liên hệ','tôi để lại thông tin thì bao giờ được liên hệ','Dạ, sau khi anh/chị để lại thông tin, cán bộ sẽ liên hệ phản hồi trong thời gian sớm nhất theo lịch làm việc. Nếu cần gấp, anh/chị gọi đường dây nóng 0903.480.985.','[\"bao gio duoc lien he\", \"khi nao can bo goi lai\", \"de lai thong tin bao lau\", \"may lau thi duoc phan hoi\"]',1,1,117,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(119,'portal_facts','Cổng có trang mạng xã hội không','cổng có trang mạng xã hội không','Dạ, anh/chị theo dõi thông tin chính thức trên Cổng thông tin điện tử này ạ. Khi cần hỗ trợ, anh/chị có thể liên hệ đường dây nóng 0903.480.985.','[\"cong co mang xa hoi khong\", \"co trang facebook khong\", \"co kenh mang xa hoi khong\", \"theo doi cong o dau\"]',1,1,118,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(120,'portal_facts','Cổng dùng trên điện thoại được không','cổng dùng trên điện thoại được không','Dạ, anh/chị có thể truy cập Cổng thông tin trên điện thoại, máy tính bảng hay máy tính qua trình duyệt web đều được ạ.','[\"dung tren dien thoai duoc khong\", \"xem tren mobile duoc khong\", \"vao bang dien thoai duoc khong\", \"mo tren may tinh bang duoc khong\"]',1,1,119,'2026-09-03 05:48:40','2026-09-03 05:48:40'),(121,'portal_facts','Tôi quên nội dung đã hỏi thì tra lại ở đâu','tôi quên nội dung đã hỏi thì tra lại ở đâu','Dạ, anh/chị có thể nhắn lại câu hỏi để tôi trả lời một lần nữa. Nếu cần lưu thông tin, anh/chị nên ghi chú lại. Nếu cần hỗ trợ trực tiếp, anh/chị có thể liên hệ Công an xã/phường nơi cư trú hoặc gọi đường dây nóng 0903.480.985.','[\"tra lai noi dung da hoi o dau\", \"xem lai cau da hoi\", \"tim lai cau tra loi cu\", \"lich su hoi dap o dau\"]',1,1,120,'2026-09-03 05:48:40','2026-09-03 05:48:40');
/*!40000 ALTER TABLE `chatbot_small_talk` ENABLE KEYS */;
